// supabase/functions/trust-badge-admin/index.ts
//
// Authenticated actions for the trust badge that need the network or the service role:
//   POST { action: "verify_domain", domain_id }  -> { status, txt_found, error? }
//
// Ownership proof = DNS TXT at _vireek-badge.<domain> with value `vireek-verify=<token>` (token generated by the DB).
// Same security model as verify-custom-domain: the caller's JWT reads the row through RLS and passes
// website_widgets_can_manage(); only then is the service role used to record the result.
//
// Deploy: supabase functions deploy trust-badge-admin     (JWT verification stays ON)

import { createClient } from "npm:@supabase/supabase-js@2.57.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};
const TXT_PREFIX = "_vireek-badge";
const MIN_SECONDS_BETWEEN_CHECKS = 10;

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

async function dohTxt(name: string): Promise<{ values: string[]; failed: boolean }> {
  try {
    const res = await fetch(`https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=TXT`, {
      headers: { accept: "application/dns-json" }, signal: AbortSignal.timeout(6000),
    });
    if (!res.ok) return { values: [], failed: true };
    const body = (await res.json()) as { Status?: number; Answer?: { type: number; data: string }[] };
    if (body.Status !== 0 && body.Status !== 3) return { values: [], failed: true }; // 3 = NXDOMAIN = definitive "no record"
    return { values: (body.Answer ?? []).filter((a) => a.type === 16).map((a) => a.data.replace(/"\s+"/g, "").replace(/^"|"$/g, "").trim()), failed: false };
  } catch {
    return { values: [], failed: true };
  }
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);

  const authHeader = req.headers.get("authorization") ?? "";
  if (!authHeader) return json({ error: "unauthorized" }, 401);
  let body: { action?: string; domain_id?: string };
  try { body = await req.json(); } catch { return json({ error: "invalid_json" }, 400); }
  if (body.action !== "verify_domain" || typeof body.domain_id !== "string") return json({ error: "invalid_request" }, 400);

  const url = Deno.env.get("SUPABASE_URL") ?? "";
  const userClient = createClient(url, Deno.env.get("SUPABASE_ANON_KEY") ?? "", {
    global: { headers: { Authorization: authHeader } }, auth: { persistSession: false },
  });
  const { data: userData } = await userClient.auth.getUser();
  if (!userData?.user) return json({ error: "unauthorized" }, 401);
  const { data: allowed } = await userClient.rpc("website_widgets_can_manage");
  if (allowed !== true) return json({ error: "forbidden" }, 403);

  // RLS proves the row belongs to the caller's account.
  const { data: row } = await userClient.from("trust_badge_domains")
    .select("id, domain, status, verification_token, last_checked_at").eq("id", body.domain_id).maybeSingle();
  if (!row) return json({ error: "not_found" }, 404);

  if (row.last_checked_at) {
    const elapsed = (Date.now() - new Date(row.last_checked_at as string).getTime()) / 1000;
    if (elapsed < MIN_SECONDS_BETWEEN_CHECKS) return json({ status: row.status, txt_found: row.status === "verified", throttled: true, error: `Please wait ${Math.ceil(MIN_SECONDS_BETWEEN_CHECKS - elapsed)}s before checking again.` }, 429);
  }

  const admin = createClient(url, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "", { auth: { persistSession: false } });
  const now = new Date().toISOString();
  const expected = `vireek-verify=${row.verification_token}`;
  const txt = await dohTxt(`${TXT_PREFIX}.${row.domain}`);
  const found = txt.values.includes(expected);

  if (!found) {
    const error = txt.failed ? "We couldn’t reach DNS just now. Try again in a minute." : "TXT record not found yet. DNS changes can take up to a few hours to propagate.";
    // A lookup failure is not proof of absence: keep a verified domain verified, otherwise mark pending/failed.
    const status = row.status === "verified" && txt.failed ? "verified" : txt.failed ? "pending" : "failed";
    await admin.from("trust_badge_domains").update({ status, verified_at: status === "verified" ? undefined : null, last_checked_at: now, last_error: error }).eq("id", row.id);
    return json({ status, txt_found: false, error });
  }

  const { error: updErr } = await admin.from("trust_badge_domains")
    .update({ status: "verified", verified_at: now, last_checked_at: now, last_error: null }).eq("id", row.id);
  if (updErr) {
    if ((updErr as { code?: string }).code === "23505") { // unique index: another account holds this domain verified
      const error = "This domain is already verified by another Vireek account.";
      await admin.from("trust_badge_domains").update({ status: "failed", last_checked_at: now, last_error: error }).eq("id", row.id);
      return json({ status: "failed", txt_found: true, error });
    }
    return json({ error: "Could not save the verification result." }, 500);
  }
  return json({ status: "verified", txt_found: true });
});
